Exercise: Personal Statistics Module (my_stats.py)
Create a module named my_stats.py with three functions: mean(), variance(), and standard_deviation().
# my_stats.py
import math

def mean(data):
    """Compute arithmetic average."""
    if not data:
        return 0.0
    return sum(data) / len(data)

def variance(data):
    """Compute sample variance: sum((x - mean)^2) / (N - 1)"""
    if len(data) &lt; 2:
        return 0.0
    m = mean(data)
    sq_diff = sum((x - m) ** 2 for x in data)
    return sq_diff / (len(data) - 1)

def standard_deviation(data):
    """Compute sample standard deviation."""
    return math.sqrt(variance(data))

if __name__ == "__main__":
    test_scores = [85, 92, 78, 90, 88]
    print("Test mean:  ", mean(test_scores))
    print("Test std-dev:", standard_deviation(test_scores))

1. Module Source Code: sci_toolkit.py
Save this file in your working folder as sci_toolkit.py:
"""
sci_toolkit.py
==============
A collection of scientific computing utilities for statistics, 
matrix transformations, and recursive algorithms.
"""

import math


# --- Part A: Statistical Helpers ---

def mean(data):
    """
    Compute the arithmetic mean of a numerical list.

    Parameters
    ----------
    data : list of float or int
        Sequence of numbers.

    Returns
    -------
    float
        The average value.
    """
    if not data:
        return 0.0
    return sum(data) / len(data)


def median(data):
    """
    Compute the median (middle value) of a list of numbers.
    """
    if not data:
        return 0.0
    sorted_data = sorted(data)
    n = len(sorted_data)
    mid = n // 2
    if n % 2 == 1:
        return float(sorted_data[mid])
    else:
        return (sorted_data[mid - 1] + sorted_data[mid]) / 2.0


def variance(data):
    """
    Calculate sample variance: sum((x - mean)^2) / (N - 1).
    """
    if len(data) &lt; 2:
        return 0.0
    m = mean(data)
    return sum((x - m) ** 2 for x in data) / (len(data) - 1)


# --- Part B: Matrix Helpers (Lists of Lists) ---

def matrix_dimensions(matrix):
    """Return (rows, cols) of a 2D matrix."""
    if not matrix or not matrix[0]:
        return (0, 0)
    return (len(matrix), len(matrix[0]))


def row_totals(matrix):
    """Calculate the sum of each row in a 2D list."""
    return [sum(row) for row in matrix]


def column_totals(matrix):
    """Calculate the sum of each column in a 2D list."""
    if not matrix or not matrix[0]:
        return []
    num_cols = len(matrix[0])
    return [sum(matrix[r][c] for r in range(len(matrix))) for c in range(num_cols)]


def transpose(matrix):
    """
    Transpose a 2D matrix (swap rows and columns).
    Uses a clean nested list comprehension.
    """
    if not matrix or not matrix[0]:
        return []
    num_rows = len(matrix)
    num_cols = len(matrix[0])
    return [[matrix[r][c] for r in range(num_rows)] for c in range(num_cols)]


# --- Part C: Recursive Helpers ---

def recursive_power(base, exponent):
    """Compute base^exponent recursively for non-negative integers."""
    if exponent == 0:
        return 1.0
    elif exponent &lt; 0:
        return 1.0 / recursive_power(base, -exponent)
    return base * recursive_power(base, exponent - 1)


def recursive_gcd(a, b):
    """Euclidean algorithm for greatest common divisor: gcd(a, b)."""
    if b == 0:
        return a
    return recursive_gcd(b, a % b)


# --- Self-Testing Guard ---
if __name__ == "__main__":
    print("Running internal self-check for sci_toolkit.py...")
    test_data = [10.0, 20.0, 30.0, 40.0, 50.0]
    print("Internal Mean test:", mean(test_data), "(Expected: 30.0)")

13.5 Raising Exceptions with raise
When writing your own scientific library, you should actively validate parameters and raise meaningful errors if arguments violate physical laws:
import math

def circle_area(radius):
    """Compute area of a circle. Radius must be non-negative."""
    if not isinstance(radius, (int, float)):
        raise TypeError(f"Radius must be numeric, got {type(radius).__name__}")
    if radius &lt; 0:
        raise ValueError(f"Radius cannot be negative! Received: {radius}")
    return math.pi * (radius ** 2)

# Calling with invalid argument
try:
    area = circle_area(-5.0)
except ValueError as e:
    print("Caught validation error:", e)

13.6 Passing Exceptions Up the Call Stack
If a function does not handle an exception, the exception automatically bubbles up to the calling function. This allows low-level helper functions to signal errors while letting high-level coordinator functions decide how to handle them.
def read_raw_value():
    return float("invalid_data")  # Raises ValueError

def experiment_runner():
    # Catches the error that originated inside read_raw_value()
    try:
        val = read_raw_value()
    except ValueError:
        print("experiment_runner: Handled bad sensor reading gracefully!")

experiment_runner()

Exercises and Mini-Lab: Safe Experimental Calculator
Create a robust command-line calculator that asks the user for two numbers and an operator (+, -, *, /), handling all potential errors cleanly:
def safe_calculator(num1_str, num2_str, op):
    try:
        a = float(num1_str)
        b = float(num2_str)

        if op == "+":
            return a + b
        elif op == "-":
            return a - b
        elif op == "*":
            return a * b
        elif op == "/":
            return a / b
        else:
            raise ValueError(f"Unknown operator: '{op}'")

    except ValueError as val_err:
        return f"Input Error: {val_err}"
    except ZeroDivisionError:
        return "Math Error: Cannot divide by zero!"

# Test cases
print("10 / 2:   ", safe_calculator("10", "2", "/"))      # 5.0
print("10 / 0:   ", safe_calculator("10", "0", "/"))      # Math Error
print("Bad text: ", safe_calculator("ten", "2", "+"))     # Input Error
print("Bad op:   ", safe_calculator("5", "3", "^"))       # Input Error

